int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_sb_info *info = sb->s_fs_info;
    struct shmem_config temp_config;
    int error = 0;

    if (parse_shmem_options(data, &temp_config) < 0) {
        return -EINVAL;
    }

    mutex_lock(&info->lock);

    if (temp_config.max_blocks < info->max_blocks ||
        temp_config.max_inodes < info->max_inodes) {
        if (shmem_check_current_usage(sb, temp_config.max_blocks, temp_config.max_inodes) < 0) {
            mutex_unlock(&info->lock);
            return -EINVAL;
        }
    }

    info->max_blocks = temp_config.max_blocks;
    info->max_inodes = temp_config.max_inodes;
    info->policy = temp_config.policy;

    mutex_unlock(&info->lock);

    return error;
}

