    return error;
}

int remount_shmem_fs(struct super_block *sb, int *flags, char *data) {
    struct shmem_config temp_config;
    int result = 0;

    if (!sb || !flags || !data) {
        return -EINVAL;
    }

    if (parse_shmem_options(data, &temp_config) < 0) {
        return -EINVAL;
    }

    spin_lock(&sb->s_lock);

